<script setup lang="ts">
import {computed} from 'vue';
import type {ReviewOptions} from '../api/contracts';
const props=defineProps<{options:ReviewOptions;busy:boolean;grade:number;allocations:Record<string,number>;allocationTotal:number;parent?:boolean}>();
const group=computed(()=>props.options.groups?.find(g=>g.grade===props.grade));
defineEmits<{replay:[];close:[];reinforce:[];grade:[value:number];allocation:[pointId:string,total:number]}>();
</script>
<template><section class="card" aria-labelledby="reviewTitle"><h2 id="reviewTitle">错题巩固</h2><template v-if="!parent"><h3>原题重练确认</h3><p>按历史内容新建 {{options.replay.total}} 道不同题，保留原有记录。</p><p v-if="!options.replay.allowed" class="error" role="alert">{{options.replay.reason}}</p><ol><li v-for="item in options.replay.items" :key="item.id">{{item.stem}}<small class="muted"> · {{item.grade}}年级 · {{item.pointName}}</small></li></ol><p class="muted">本次重新作答、保存和提交，不会清除旧错误，也不会自动标记已掌握。</p><div class="two"><button class="secondary" :disabled="busy" @click="$emit('close')">返回选择</button><button class="primary" :disabled="busy||!options.replay.allowed" @click="$emit('replay')">开始原题重练</button></div></template><h3>同知识点强化</h3><p class="muted">根据所选错题的历史年级与知识点，从当前可用题库抽题。每次选择一个年级组，合计1—100题。</p><label for="reinforceGrade">强化年级组</label><select id="reinforceGrade" :value="grade" :disabled="busy" @change="$emit('grade',Number(($event.target as HTMLSelectElement).value))"><option v-for="g in options.groups" :key="g.grade" :value="g.grade">{{g.grade}}年级</option></select><div v-for="p in group?.points" :key="p.pointId"><label :for="'reinforce-'+p.pointId">{{p.pointName}} · 可用{{p.available}}题</label><input :id="'reinforce-'+p.pointId" type="number" min="1" max="100" step="1" :value="allocations[p.pointId]" :disabled="busy" @input="$emit('allocation',p.pointId,Number(($event.target as HTMLInputElement).value))"><p v-if="p.reason" class="error">{{p.reason}}</p></div><p>本次共 {{allocationTotal}} 题</p><button class="primary" :disabled="busy||!group" @click="$emit('reinforce')">{{parent?'生成强化题目预览':'开始同类强化'}}</button><button v-if="parent" class="secondary" :disabled="busy" @click="$emit('close')">返回选择</button></section></template>
